    states=['inactive','active']+(['completed'] if slug in completed else [])
    motions=['cut-paper-pop','scale-bounce','paper-slide']
    if group in ('publishing','analytics'): motions=['stamp-impact','paper-slide','scale-bounce']
    elif group in ('planning','production'): motions=['paper-slide','cut-paper-pop','drop-and-settle']
    elif group in ('editing','design'): motions=['unfold','cut-paper-pop','scale-bounce']
