sym_js=',\n'.join(json.dumps(k)+': `'+v.replace('`','\\`')+'`' for k,v in symbols.items())
component=f'''window.NexCreatorIcons = (() => {{
  const registry=window.NEX_CREATOR_ICONS||[],NS='http://www.w3.org/2000/svg';
  const q=v=>typeof v==='string'?document.querySelector(v):v;
  const getDef=v=>typeof v==='object'?v:registry.find(x=>x.id===v||x.slug===v);
  const clamp=(v,a=0,b=1)=>Math.min(b,Math.max(a,v));
  const symbols={{\n{sym_js}\n  }};
  function paperLayers(){{return `<g class="icon-shadow-layer"><path class="icon-paper-shadow" d="M16 27Q20 14 37 15L82 12Q100 17 103 34L106 79Q101 99 82 104L37 106Q18 101 14 83L12 43Q12 32 16 27Z"/></g><g class="icon-paper-layer"><path class="icon-paper-shape" d="M13 23Q20 12 36 14L84 11Q100 16 105 33L107 78Q103 98 83 103L36 106Q17 100 13 82L10 42Q10 30 13 23Z"/><path class="icon-paper-edge" d="M18 25Q24 18 38 19L82 16Q94 19 99 35L101 76Q97 91 80 97L38 99Q23 94 19 80L16 43Q16 31 18 25Z"/><circle class="icon-active-ring" cx="60" cy="60" r="49"/></g>`}}
  function stateLayer(){{return `<g class="icon-state-layer"><g class="icon-complete-badge"><circle cx="91" cy="29" r="15"/><path d="M84 29L89 34L99 23"/></g></g>`}}
  function sizeBand(size){{return size<=56?'small':size>=144?'large':'medium'}}
  function create(value,config={{}}){{const def=getDef(value);if(!def)throw new Error(`Unknown creator icon: ${{value}}`);const size=Number(config.size||96),treatment=config.treatment||'paper-cutout',allowed=def.states||['inactive','active'];const state=allowed.includes(config.state)?config.state:(config.state==='completed'&&allowed.includes('completed')?'completed':'active');const el=document.createElement('div');el.className='nex-icon nex-creator-icon';el.dataset.iconId=def.id;el.dataset.componentId=def.id;el.dataset.slug=def.slug;el.dataset.treatment=treatment;el.dataset.state=state;el.dataset.sizeBand=sizeBand(size);el.style.setProperty('--icon-size',`${{size}}px`);el.setAttribute('role','img');el.setAttribute('aria-label',config.accessibilityLabel||def.accessibilityLabel);const svg=document.createElementNS(NS,'svg');svg.setAttribute('viewBox','0 0 120 120');svg.setAttribute('class','nex-icon-svg');svg.setAttribute('aria-hidden','true');svg.innerHTML=`${{paperLayers()}}<g class="icon-symbol-layer">${{symbols[def.slug]}}</g><g class="icon-accent-layer"><path class="icon-accent-stroke icon-accent-mark" d="M88 92L97 83"/></g>${{stateLayer()}}`;el.appendChild(svg);const grain=document.createElement('span');grain.className='icon-paper-grain';grain.setAttribute('aria-hidden','true');el.appendChild(grain);if(config.showLabel){{const label=document.createElement('span');label.className='icon-label';label.textContent=config.label||def.name;el.appendChild(label)}}el.__iconConfig={{size,treatment,state,label:config.label||def.name}};return el}}
  class CombinedTimeline{{constructor(entries=[]){{this.entries=entries;this.now=0;this.paused=true;this.timer=null;this._duration=Math.max(0,...entries.map(x=>(x.offset||0)+x.timeline.duration()))}}duration(){{return this._duration}}seek(t){{this.now=clamp(Number(t)||0,0,this._duration);for(const e of this.entries){{const local=this.now-(e.offset||0);e.timeline.seek(local<=0?0:local>=e.timeline.duration()?e.timeline.duration():local)}}return this}}time(v){{return v==null?this.now:this.seek(v)}}progress(v){{return v==null?(this._duration?this.now/this._duration:0):this.seek(v*this._duration)}}pause(){{if(this.timer)cancelAnimationFrame(this.timer);this.timer=null;this.paused=true;return this}}play(from){{if(from!=null)this.seek(from);this.pause();this.paused=false;const initial=this.now,start=performance.now();const tick=now=>{{if(this.paused)return;const t=initial+(now-start)/1000;if(t>=this._duration){{this.seek(this._duration);this.pause();return}}this.seek(t);this.timer=requestAnimationFrame(tick)}};this.timer=requestAnimationFrame(tick);return this}}restart(){{this.seek(0);return this.play()}}kill(){{this.entries.forEach(x=>x.timeline.kill?.());return this.pause()}}}}
  function pathDraw(tl,path,start,duration,ease='power2.out'){{if(!path)return;let len=180;try{{len=path.getTotalLength()||180}}catch(_){{}}path.style.strokeDasharray=String(len);tl.addUpdate(start,duration,p=>{{path.style.strokeDashoffset=String(len*(1-p));path.style.opacity=String(p)}},ease)}}
  function staggerScale(tl,nodes,start,duration,axis='scale'){{const list=[...nodes],seg=duration/Math.max(1,list.length+1);list.forEach((n,i)=>{{const from={{opacity:0,scale:.2}},to={{opacity:1,scale:1,duration:seg*2,ease:'back.out(1.7)'}};if(axis==='scaleY'){{from.scale=1;from.scaleY=.08;to.scaleY=1;delete to.scale}}tl.fromTo(n,from,to,start+i*seg)}})}}
  function genericInternal(el,o){{const tl=NexMotion.createTimeline(),symbol=el.querySelector('.icon-symbol-layer'),accent=el.querySelector('.icon-accent-layer');tl.fromTo(symbol,{{y:7,scale:.9,opacity:.55}},{{y:0,scale:1,opacity:1,duration:o.duration*.68,ease:'power2.out'}},0);tl.fromTo(accent,{{opacity:0,scale:.6}},{{opacity:1,scale:1,duration:o.duration*.5,ease:'back.out(1.7)'}},o.duration*.28);return tl}}
  function countText(tl,node,start,duration,end,format){{if(!node)return;tl.addUpdate(start,duration,p=>{{node.textContent=format(Math.round(end*p))}},'power2.out')}}
  function bespokeInternal(el,slug,o){{const tl=NexMotion.createTimeline(),S=s=>el.querySelector(s),SA=s=>el.querySelectorAll(s),d=o.duration;switch(slug){{
    case 'camera': tl.fromTo(S('.part-camera-shutter'),{{rotation:-100,scale:.35,opacity:.25}},{{rotation:0,scale:1,opacity:1,duration:d*.62,ease:'back.out(1.7)'}},0);tl.to(S('.part-camera-shutter'),{{scale:.62,rotation:38,duration:d*.18,ease:'power2.in'}},d*.64);tl.to(S('.part-camera-shutter'),{{scale:1,rotation:0,duration:d*.24,ease:'back.out(1.7)'}},d*.82);break;
    case 'video-camera': tl.fromTo(S('.part-video-body'),{{scale:.82,y:7}},{{scale:1,y:0,duration:d*.48,ease:'back.out(1.7)'}},0);tl.fromTo(S('.part-record-dot'),{{opacity:.2,scale:.35}},{{opacity:1,scale:1.25,duration:d*.35,ease:'back.out(1.7)'}},d*.25);tl.to(S('.part-record-dot'),{{scale:1,duration:d*.22,ease:'power2.out'}},d*.6);break;
    case 'microphone': staggerScale(tl,SA('.part-mic-wave path'),0,d*.76,'scaleY');tl.fromTo(S('.part-mic-body'),{{y:15,scaleY:.75}},{{y:0,scaleY:1,duration:d*.55,ease:'back.out(1.7)'}},0);break;
    case 'speaker': tl.fromTo(S('.part-speaker-box'),{{scale:.82,x:-8}},{{scale:1,x:0,duration:d*.5,ease:'back.out(1.7)'}},0);[...SA('.part-speaker-waves path')].forEach((n,i)=>pathDraw(tl,n,d*(.18+i*.16),d*.48));break;
    case 'audio-waveform': staggerScale(tl,SA('.part-waveform path'),0,d*.85,'scaleY');break;
    case 'storyboard': [...SA('.part-story-card')].forEach((n,i)=>tl.fromTo(n,{{x:(i%2?22:-22),y:(i<2?-18:18),rotation:(i%2?8:-8),opacity:0}},{{x:0,y:0,rotation:0,opacity:1,duration:d*.48,ease:'back.out(1.7)'}},i*d*.11));break;
    case 'timeline': tl.fromTo(S('.part-playhead'),{{x:-13,opacity:.4}},{{x:52,opacity:1,duration:d*.82,ease:'power2.inOut'}},0);break;
    case 'caption': [...SA('.part-caption-lines > *')].forEach((n,i)=>tl.fromTo(n,{{scaleX:.05,opacity:0}},{{scaleX:1,opacity:1,duration:d*.42,ease:'power3.out'}},i*d*.2));break;
    case 'crop': [...SA('.part-crop-guides path')].forEach((n,i)=>tl.fromTo(n,{{x:i%2?18:-18,y:i<2?-18:18,opacity:0}},{{x:0,y:0,opacity:1,duration:d*.54,ease:'back.out(1.7)'}},i*d*.08));break;
    case 'layers': [...SA('.part-layer')].forEach((n,i)=>tl.fromTo(n,{{y:-25+i*18,opacity:.15,scale:.82}},{{y:0,opacity:1,scale:1,duration:d*.5,ease:'back.out(1.7)'}},i*d*.14));break;
    case 'transition': tl.fromTo(S('.part-transition-left'),{{x:-24,opacity:.35}},{{x:0,opacity:1,duration:d*.48,ease:'power3.out'}},0);tl.fromTo(S('.part-transition-right'),{{x:24,opacity:.35}},{{x:0,opacity:1,duration:d*.48,ease:'power3.out'}},0);tl.fromTo(S('.part-transition-wipe'),{{x:-52,scaleX:.2,opacity:0}},{{x:28,scaleX:1,opacity:1,duration:d*.78,ease:'power2.inOut'}},d*.16);break;
    case 'render': pathDraw(tl,S('.part-render-ring'),0,d*.78,'power2.inOut');pathDraw(tl,S('.part-render-tick'),d*.6,d*.34);break;
    case 'export': tl.fromTo(S('.part-export-arrow'),{{x:-20,y:18,opacity:0}},{{x:8,y:-8,opacity:1,duration:d*.62,ease:'power3.out'}},0);tl.fromTo(S('.part-export-check'),{{opacity:0,scale:.2}},{{opacity:1,scale:1,duration:d*.38,ease:'back.out(1.7)'}},d*.55);break;
    case 'livestream': tl.fromTo(S('.part-live-dot'),{{scale:.3,opacity:.25}},{{scale:1.25,opacity:1,duration:d*.36,ease:'back.out(1.7)'}},0);tl.to(S('.part-live-dot'),{{scale:1,duration:d*.2}},d*.36);[...SA('.part-live-rings path')].forEach((n,i)=>tl.fromTo(n,{{opacity:0,scale:.55}},{{opacity:1,scale:1,duration:d*.54,ease:'power2.out'}},d*(.2+i*.18)));break;
    case 'subscriber': countText(tl,S('.part-subscriber-count'),0,d*.82,12800,v=>v<1000?String(v):(v/1000).toFixed(v<10000?1:0)+'K');tl.fromTo(S('.part-subscriber-count'),{{opacity:0,y:8}},{{opacity:1,y:0,duration:d*.4,ease:'power2.out'}},0);break;
    case 'view-count': countText(tl,S('.part-view-count'),0,d*.82,1200000,v=>v<1000?String(v):(v/1000000).toFixed(1)+'M');tl.fromTo(S('.part-view-count'),{{opacity:0,scale:.7}},{{opacity:1,scale:1,duration:d*.4,ease:'back.out(1.7)'}},0);break;
    case 'analytics': staggerScale(tl,SA('.part-analytics-bars path'),0,d*.72,'scaleY');pathDraw(tl,S('.part-analytics-line'),d*.32,d*.55);break;
    case 'publish': tl.fromTo(S('.part-publish-plane'),{{x:-30,y:20,rotation:-14,opacity:.2}},{{x:8,y:-8,rotation:0,opacity:1,duration:d*.65,ease:'power3.out'}},0);tl.fromTo(S('.part-publish-check'),{{opacity:0,scale:.2}},{{opacity:1,scale:1,duration:d*.4,ease:'back.out(1.7)'}},d*.58);break;
    default:return genericInternal(el,o);
  }}return tl}}
  function animate(target,config={{}}){{const el=q(target),def=getDef(el?.dataset.iconId);if(!el||!def)throw new Error('Creator icon target or definition missing');const motion=config.motion||def.defaultMotion,duration=Number(config.duration||def.duration.recommended),energy=config.energy||config.motionEnergy||'medium';[...el.querySelectorAll('[data-motion-layer]')].forEach(x=>x.remove());const entrance=NexMotion.apply(el,motion,{{duration:Math.max(.35,duration*.72),energy,intensity:config.intensity??1,ease:config.ease}});const internal=def.bespokeInternalMotion?bespokeInternal(el,def.slug,{{duration:Math.max(.4,duration*.82),energy}}):genericInternal(el,{{duration:Math.max(.4,duration*.72),energy}});const combined=new CombinedTimeline([{{timeline:entrance,offset:0}},{{timeline:internal,offset:Math.max(.08,duration*.24)}}]);combined.seek(0);el.__tl=combined;return combined}}
  function setState(target,state){{const el=q(target),def=getDef(el?.dataset.iconId);if(!el||!def)return el;if(!(def.states||[]).includes(state))state=(def.states||['active']).includes('active')?'active':def.states[0];el.dataset.state=state;el.__iconConfig.state=state;return el}}
  function setTreatment(target,treatment){{const el=q(target);if(el){{el.dataset.treatment=treatment;el.__iconConfig.treatment=treatment}}return el}}
  function setSize(target,size){{const el=q(target);if(el){{size=Number(size)||96;el.style.setProperty('--icon-size',`${{size}}px`);el.dataset.sizeBand=sizeBand(size);el.__iconConfig.size=size}}return el}}
  function update(target,config={{}}){{const el=q(target),def=getDef(el?.dataset.iconId);if(!el||!def)throw new Error('Creator icon target missing');const next=create(def,{{...el.__iconConfig,...config}});el.replaceWith(next);return next}}
  return {{registry,getDef,create,animate,setState,setTreatment,setSize,update,CombinedTimeline}};
}})();\n'''
