explorer='''<!doctype html><html lang="en" data-paper-style="clean-editorial"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NexStudio Creator, Media and Publishing Icons</title><link rel="stylesheet" href="styles/tokens.css"><link rel="stylesheet" href="styles/paper.css"><link rel="stylesheet" href="styles/motion.css"><link rel="stylesheet" href="styles/icons.css"><link rel="stylesheet" href="styles/creator-icons.css"><link rel="stylesheet" href="styles/icon-explorer.css"><link rel="stylesheet" href="styles/creator-explorer.css"></head><body><div class="icon-app"><aside class="icon-sidebar"><div class="icon-brand">NEXSTUDIO<br>CREATOR ICONS</div><div class="icon-kicker">Batch 5 · 48 layered SVG components</div><div class="icon-controls"><label class="icon-control">Paper style<select id="creatorStyle"><option value="clean-editorial">Clean editorial</option><option value="handmade-scrapbook">Handmade scrapbook</option><option value="technical-notebook">Technical notebook</option><option value="bold-paper-collage">Bold paper collage</option></select></label><label class="icon-control">Palette<select id="creatorPalette"><option value="warm">Warm cream / plum</option><option value="cobalt">White / cobalt</option><option value="charcoal">Charcoal / red</option></select></label><div class="creator-colours"><label>Primary<input id="creatorPrimary" type="color" value="#6d45d8"></label><label>Secondary<input id="creatorSecondary" type="color" value="#ffb648"></label><label>Accent<input id="creatorAccent" type="color" value="#f25f3a"></label></div><label class="icon-control">Treatment<select id="creatorTreatment"><option value="paper-cutout">Paper cutout</option><option value="printed-outline">Printed outline</option></select></label><label class="icon-control">Entrance<select id="creatorMotion"><option value="cut-paper-pop">Cut-paper pop</option><option value="paper-slide">Paper slide</option><option value="scale-bounce">Scale bounce</option><option value="drop-and-settle">Drop and settle</option><option value="stamp-impact">Stamp impact</option><option value="unfold">Unfold</option></select></label><label class="icon-control">State<select id="creatorState"><option value="active">Active</option><option value="inactive">Inactive</option><option value="completed">Completed where supported</option></select></label><label class="icon-control">Scale<select id="creatorSize"><option value="42">Small · 42px</option><option value="96" selected>Medium · 96px</option><option value="176">Large · 176px</option></select></label><label class="icon-control">Motion energy<select id="creatorEnergy"><option value="low">Low</option><option value="medium" selected>Medium</option><option value="high">High</option></select></label><label class="icon-control">Search<input id="creatorSearch" type="search" placeholder="camera, caption, publish…"></label><label class="icon-control"><button id="creatorReplayAll">REPLAY VISIBLE ICONS</button></label></div></aside><main class="icon-main"><header class="icon-hero"><h1>CREATE.<br>EDIT. PUBLISH.</h1><div class="icon-counter"><span id="creatorCount">48</span> / 48</div></header><p class="icon-summary">Creator, media-production and publishing concepts are implemented as reusable layered SVG components with semantic internal motion—not repeated generic bounce animations.</p><div class="icon-toolbar"><button class="icon-filter active" data-filter="all">All</button><button class="icon-filter" data-filter="bespoke">Bespoke motion</button><button class="icon-filter" data-filter="media">Media</button><button class="icon-filter" data-filter="production">Production</button><button class="icon-filter" data-filter="publishing">Publishing</button><button class="icon-filter" data-filter="analytics">Analytics</button></div><section id="creatorGrid" class="icon-grid-surface" aria-live="polite"></section></main></div><aside id="creatorManifest" class="icon-manifest-panel"><header><h2>Component manifest</h2><button id="closeCreatorManifest">CLOSE</button></header><pre></pre></aside><script src="vendor/gsap-compat.js"></script><script src="runtime/theme.js"></script><script src="runtime/motion-registry.js"></script><script src="runtime/motion-engine.js"></script><script src="runtime/creator-icon-registry.js"></script><script src="components/creator-icons.js"></script><script src="runtime/creator-icon-explorer.js"></script></body></html>'''
(root/'creator-icon-explorer.html').write_text(explorer)
(root/'styles/creator-explorer.css').write_text('''.creator-colours{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.creator-colours label{font:800 8px var(--mono-font);text-transform:uppercase}.creator-colours input{width:100%;height:34px;border:2px solid var(--ink);background:var(--paper-surface);padding:2px}.creator-group{font:900 9px var(--mono-font);text-transform:uppercase;color:var(--ink-muted)}''')
explorer_js='''(()=>{const $=s=>document.querySelector(s),grid=$('#creatorGrid'),count=$('#creatorCount'),manifest=$('#creatorManifest');const c={style:$('#creatorStyle'),palette:$('#creatorPalette'),treatment:$('#creatorTreatment'),motion:$('#creatorMotion'),state:$('#creatorState'),size:$('#creatorSize'),energy:$('#creatorEnergy'),search:$('#creatorSearch')};let filter='all';function matches(def){const term=c.search.value.trim().toLowerCase(),hay=[def.name,def.slug,def.group,...def.keywords,...def.intents].join(' ').toLowerCase();if(term&&!hay.includes(term))return false;if(filter==='bespoke'&&!def.bespokeInternalMotion)return false;if(!['all','bespoke'].includes(filter)&&def.group!==filter)return false;return true}function state(def){return def.states.includes(c.state.value)?c.state.value:(c.state.value==='completed'?'active':def.states[0])}function card(def){const a=document.createElement('article');a.className='icon-card';a.dataset.iconId=def.id;a.innerHTML=`<header class="icon-card-head"><div><h3>${def.name}</h3><div class="icon-card-id">${def.id}</div></div><div class="icon-card-badges"><span class="icon-card-badge">${def.bespokeInternalMotion?'bespoke':'shared'}</span><span class="icon-card-badge">${def.group}</span></div></header><div class="icon-stage"></div><div class="creator-group">${def.intents.join(' · ')}</div><footer class="icon-card-actions"><button data-action="replay">Replay</button><button data-action="manifest">Manifest</button></footer>`;const icon=NexCreatorIcons.create(def,{size:Number(c.size.value),treatment:c.treatment.value,state:state(def)});a.querySelector('.icon-stage').appendChild(icon);icon.__tl=NexCreatorIcons.animate(icon,{motion:c.motion.value,energy:c.energy.value});icon.__tl.seek(icon.__tl.duration());a.querySelector('[data-action=replay]').onclick=()=>icon.__tl.restart();a.querySelector('[data-action=manifest]').onclick=()=>{manifest.querySelector('pre').textContent=JSON.stringify(def,null,2);manifest.classList.add('open')};return a}function render(){NexTheme.setStyle(c.style.value);NexTheme.applyPalette(c.palette.value);NexTheme.setEnergy(c.energy.value);const defs=NexCreatorIcons.registry.filter(matches);grid.replaceChildren(...defs.map(card));count.textContent=defs.length}Object.values(c).forEach(el=>el.addEventListener(el===c.search?'input':'change',render));document.querySelectorAll('.icon-filter').forEach(btn=>btn.onclick=()=>{filter=btn.dataset.filter;document.querySelectorAll('.icon-filter').forEach(x=>x.classList.toggle('active',x===btn));render()});[['creatorPrimary','primary'],['creatorSecondary','secondary'],['creatorAccent','accent']].forEach(([id,key])=>$('#'+id).oninput=e=>document.documentElement.style.setProperty('--'+key,e.target.value));$('#creatorReplayAll').onclick=()=>[...grid.querySelectorAll('.nex-icon')].forEach((el,i)=>setTimeout(()=>el.__tl?.restart(),i*24));$('#closeCreatorManifest').onclick=()=>manifest.classList.remove('open');window.NexCreatorExplorer={render,get filter(){return filter}};render()})();'''
